// Names generated by the compiler are never reported by lint rules
module lintvlogrules3(input logic clk, input logic rst, input logic d,
                      output logic q);
  logic r;
  logic [3:0] n;

  always @(posedge clk) begin : blk
    if (rst) begin
      r <= 1'b0;
      disable blk;
    end
    r <= d;
    for (int i = 0; i < 4; i++) begin : inner
      if (i == 2) disable inner;
      n[i] <= d;
    end
  end

  // A loop index shared by several blocks
  integer k;
  logic [3:0] m1, m2;
  always @(posedge clk)
    for (k = 0; k < 4; k = k + 1) m1[k] <= d;
  always @(posedge clk)
    for (k = 0; k < 4; k = k + 1) m2[k] <= !d;

  assign q = r;

  // An asynchronous disable iff generates a variable and a process
  assert property (@(posedge clk) disable iff (rst) d |-> r);
  assert property (@(posedge clk) disable iff (rst) !d |-> !r);
endmodule
